(async()=>{const b=await chromium.launch({channel:'msedge',headless:true});const p=await b.newPage({viewport:{width:1200,height:650}});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://127.0.0.1:5173/flip-preview.html');await p.waitForSelector('canvas');await p.waitForTimeout(600);await p.screenshot({path:'flip-preview.png'});const before=await p.locator('canvas').evaluate(c=>c.toDataURL());await p.click('#demo');await p.waitForTimeout(180);const during=await p.locator('canvas').evaluate(c=>c.toDataURL());await p.screenshot({path:'flip-motion.png'});await p.waitForTimeout(1900);const after=await p.locator('canvas').evaluate(c=>c.toDataURL());if(before===during||before!==after)throw Error('Demo or restore failed');const checks=await p.evaluate(async()=>{const {FlipState,FlipRenderer}=await import('/src/flip.ts');const s=new FlipState();s.update('2359',0,{});s.update('0000',1000,{});if(s.from!=='2359'||s.to!=='0000'||s.progress(1200,{})!==.5)throw Error('Rollover');if(s.progress(1000,{animate:false})!==1)throw Error('Disable');const r=new FlipRenderer();const out=r.draw('1111','8888',.5,240,600);return {rollover:true,disabled:true,size:[out.width,out.height]}});for(const path of ['src/plugin/actions/flip.ts','src/pages/actions/flip.vue']){const response=await p.request.get('http://127.0.0.1:5173/'+path);if(response.status()!==200)throw Error('Compile '+path)}console.log(JSON.stringify({checks,errors,animation:true,restore:true}));await b.close();if(errors.length)process.exitCode=1})().catch(e=>{console.error(e);process.exitCode=1});